#
# ROM size optimization: version_script for
# libnotification_subscriber_extension_module.z.so.
# Exports OHOS_EXTENSION_GetExtensionModule as the extension framework entry
# point. vtable/typeinfo exported for CFI cross-dso virtual calls on
# NotificationSubscriberExtensionModuleLoader [PR#4766].
# No napi_module export needed — module registration works via
# __attribute__((constructor)) which runs via .init_array.

1.0 {
  global:
    OHOS_EXTENSION_GetExtensionModule;
    *vtable*for*;
    *typeinfo*for*;
    *VTT*for*;
  local:
    *;
};
